sampler sampler_worms;
float3 color, mus;
float dx,dy;
shader_body {


float2 uv1 = (uv-.5) * aspect.xy;

float2 uv6 = uv1;
float z = q10*48*length(((uv1.x)*(uv1.y)));
float2 d = normalize(uv1);
float2 rs = clamp(tan(z)*d,-2,2);
uv += .1*lum(GetBlur1(uv))*float2 (0,1);
uv -= rs/450;

uv6 = .4*sin(uv*6+rand_frame*6);
mus = .1/(length(uv6));
mus *= .5*(1+roam_cos);

float3 blur = GetBlur2(frac(uv));

float3 crisp= tex2D(sampler_main,uv);

float3 ret1 = crisp - blur*.12 + .1*mus;

q25 = 1;
ret = q25*(ret1*.99-.028) + (1-q25)* GetPixel(uv_orig);

}

