suksma - dotes hostile undertake - autoc.warp:
shader_body
{
float2 pixelsize = texsize.zw;
float1 conwar = tex2D( sampler_pw_main, uv + float2(-1,-1)*pixelsize).x;
       conwar += tex2D( sampler_pw_main, uv + float2(0,-1)*pixelsize).x;
       conwar += tex2D( sampler_pw_main, uv + float2(1,-1)*pixelsize).x;

       conwar += tex2D( sampler_pw_main, uv + float2(-1,0)*pixelsize).x;
       conwar += tex2D( sampler_pw_main, uv + float2(1,0)*pixelsize).x;

       conwar += tex2D( sampler_pw_main, uv + float2(-1,1)*pixelsize).x;
       conwar += tex2D( sampler_pw_main, uv + float2(0,1)*pixelsize).x;
       conwar += tex2D( sampler_pw_main, uv + float2(1,1)*pixelsize).x;

float1 conwag = tex2D( sampler_pw_main, uv + float2(-1, 1)*pixelsize).z;
       conwag += tex2D( sampler_pw_main, uv + float2(1,-1)*pixelsize).z;
       conwag += tex2D( sampler_pw_main, uv + float2(1,-1)*pixelsize).z;

       conwag += tex2D( sampler_pw_main, uv + float2(-1,0)*pixelsize).z;
       conwag += tex2D( sampler_pw_main, uv + float2(1,0)*pixelsize).z;

       conwag += tex2D( sampler_pw_main, uv + float2(-1,1)*pixelsize).z;
       conwag += tex2D( sampler_pw_main, uv + float2(-1,1)*pixelsize).z;
       conwag += tex2D( sampler_pw_main, uv + float2(0,-1)*pixelsize).z;

float1 conwab = tex2D( sampler_pw_main, uv + float2(1,-1)*pixelsize).y;
       conwab += tex2D( sampler_pw_main, uv + float2(1,1)*pixelsize).y;
       conwab += tex2D( sampler_pw_main, uv + float2(0,-1)*pixelsize).y;

       conwab += tex2D( sampler_pw_main, uv + float2(0,0)*pixelsize).y;
       conwab += tex2D( sampler_pw_main, uv + float2(-1,-1)*pixelsize).y;

       conwab += tex2D( sampler_pw_main, uv + float2(-1,1)*pixelsize).y;
       conwab += tex2D( sampler_pw_main, uv + float2(-1,1)*pixelsize).y;
       conwab += tex2D( sampler_pw_main, uv + float2(1,-1)*pixelsize).y;

float1 p = saturate (tex2D( sampler_pw_main, uv).x);


ret.x = saturate((1-abs(conwar-3)))*((1+roam_sin.z)*.75-p);
ret.y = saturate((1-abs(conwag-3)))*((1+roam_cos.y)*.8-p);
ret.z = saturate((1-abs(conwab-3)))*((1+roam_sin.x)*.86-p);
ret.x += saturate(max(1-abs(conwar-2),(1+roam_cos.z)*.93-abs(conwag-3)))*p;
ret.y += saturate(max(1-abs(conwag-2),(1+roam_sin.y)*1.01-abs(conwab-3)))*p;
ret.z += saturate(max(1-abs(conwab-2),(1+roam_cos.x)*1.10-abs(conwar-3)))*p;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*roam_cos.y && ret.x<= q24*roam_sin.x)ret.y -= (noise9).x*.5; 
if(ret.y> q22*roam_sin.x && ret.y<= q25*roam_cos.x)ret.z -= (noise9).y*.5; 
if(ret.z> q23*roam_cos.x && ret.z<= q26*roam_sin.y)ret.x -= (noise9).z*.5; 


}

suksma - dotes hostile undertake - autoc.comp:
shader_body
{
    uv = 0.05 + 0.9*uv;

ret = GetPixel(uv);
    uv += -.05*tan(3*(ret.zz+ret.yx));


    // equivalent of a laplacian: [center*4 - each of the 4 neighbors*1]
    ret = 0;
    ret += tex2D(sampler_main, uv ).xyz*4;
    ret -= GetBlur1(uv)*3;

    // little bit of noise:
    ret *= 1 + 0.12*(tex2D(sampler_noise_lq, rand_frame.xy 
           + uv*texsize.xy*texsize_noise_lq.zw).xxx*2-1);

    // palettize:
    ret = pow(ret, float3(0.5, 0.5, 0.7));

    ret = (ret-0.1)*1.1;

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q30 
                     );
if(ret.x> q26*roam_cos.y && ret.x<= q23*roam_sin.x)ret.z += (noise9).x*.5; 
if(ret.y> q25*roam_sin.x && ret.y<= q22*roam_cos.x)ret.x += (noise9).y*.5; 
if(ret.z> q24*roam_cos.x && ret.z<= q21*roam_sin.y)ret.y += (noise9).z*.5; 
}

