ret.x += GetBlur1(uv_orig).z*.05 + GetBlur3(uv_orig).z*.05;
ret.z -= ret.x;

float2 pixelsize = texsize.zw;
ret.y = saturate(tex2D( sampler_pw_main,uv_orig).y);

float1 conway = tex2D( sampler_pw_main, uv_orig + float2(-1,-1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(0,-1)*pixelsize).y;
