   float2 dither_uv = uv*texsize.xy*texsize_noise_lq.zw*diffusionFactor;

   float2 d = texsize.zw*pixelDistance;
   float1 dx = ( 2*GetBlur1(uv_y + float2(1,0)*d) - 2*GetBlur1(uv_y-float2(1,0)*d) ).y*0.5;
   float1 dy = ( 2*GetBlur1(uv_y + float2(0,1)*d) - 2*GetBlur1(uv_y-float2(0,1)*d) ).y*0.5;

   float2 my_uv = uv_y + float2(dx,dy)*texsize.zw*motionStrength;

   ret.y = tex2D( sampler_fw_main, saturate(my_uv)).y;

   ret.y += (ret - GetBlur1(uv_y)).y*0.025 + decay;


   ret.y += (tex2D(sampler_noise_lq, dither_uv).y-0.5)*0.02;

