uv8 = uv7;
float dist = length(uv8);
dist *= (abs(uv1.x) + abs(uv1.y))+ q32;

float ang2 = atan2 (uv8.y,uv8.x);
ang2 =  1*floor (1* ang2);
float2 dir = .095*uv8+float2 (cos(ang2), sin(ang2));

z = (1-cos(8*dist));
z *= .200*saturate (lum(z));

//ADD
float mask = (z <= 1); //momentan beliebig
rs = q28*rs + (1-q28)*rs.yx;
uv += (1-mask)*3*(rs.yx) + .5*mask*z*normalize(z.x);

//ZENTRALSTRAHL
uv6 = mul (uv1,float2x2(_qb*.50));
mus = .25*abs(0.0225/(sqrt(uv6.x)+.0))*(.3);

//DOTS
float2 uv2 = 8*uv1+.3*sin(uv1*16+4*float2 (q5,q6));
uv2 *= 2.6;
float3 dots = q26*saturate(.00065/(length(uv2)));
float3 blur = GetBlur1(frac(uv));
float3 crisp= GetPixel(uv);
float3 diff = (crisp) - .5*blur;
float3 ret1 = crisp + mus + dots;

float3 mod = tex2D (sampler_noise_lq,50*uv+time*.1)-.25;
mod = .98 - mod*diff;

ret = (1-mask)*ret1*mod + mask*ret1*mod;
ret *= float3(.89,.96,.965)+.05*tex2D(sampler_noise_lq,uv);
ret += .015*float3(1,.5,.9)*lum(uv_orig);


ret *= .96- .1;

}

