shader_body
{

   ret = tex2D(sampler_main, uv).xyz;
//    ret += GetBlur1(uv)*0.4; 
float2 uv2 = uv*.8+.1*tan(1.55*ret.xy)-.02*sin(1.33*ret.yx)-.01*bass_att;
   ret = tex2D(sampler_main,uv2);
    ret += GetBlur1(uv2); 
    // palettize:
    ret = pow(lum(ret), float3(0.3, 1+.5*roam_sin.x, 1.8));

    // invert
    ret = saturate(ret);
    ret *= 1.25*ret;
    //ret.xyz *= 2; // a little bit of overbright
ret-=roam_sin*roam_cos.zxy;
}

