sampler sampler_pw_noise_lq;

float3 neu, ret1;
float2 rs2,rs0,rss,uv1,uv2;
float ang2,c,s;
float2x2 rota = float2x2(.7,.7,-.7,.7);
shader_body
{
uv -= 0.5;
uv *= aspect.xy;    

rs0.x = atan2(uv.y, uv.x)/3.1416*2;
rs0.y = .02/(length (uv));
rss = float2 (rs0.x,rs0.y+time);
rss = mul(rss,float2x2(.7,.7,-.7,.7));
float noise = (tex2D(sampler_pw_noise_lq,rss/32)-.7 >= 0);
rss = abs(frac(rss*8)-.5);
float3 dots = saturate(.04/length(rss)) *noise;

rss = float2 (rs0.x*2,rs0.y+time/2);
rss = mul(rss,float2x2(.7,.7,-.7,.7));
noise = (tex2D(sampler_pw_noise_lq,rss/32)-.7 >= 0);
rss = abs(frac(rss*8)-.5);
dots += saturate(.04/length(rss)) * noise;

dots *= saturate(.04/abs(.01/rs0.y-q6))+.0;
dots *= dots*2;

float3 ret1 = 0;
int anz = 2;
int n = 0;
while (n <= anz) {
    ang2 = 6.28*n/anz;
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;

    neu = GetPixel(uv2+.5) + GetBlur1(uv2+.5);
    ret1 = max(ret1,neu);
n++;
}


ret = ret1 + dots*(1+ret1);
ret-=roam_sin.wzy*roam_cos.zxy;
}

