shader_body
{

     rand_preset = max(.2,min(.85,rand_preset));
    float2 uv_zero = uv;
    float2 uv2 = float2( floor(uv.x*10), floor(uv.y*10) )*0.1 
               + rand_preset.xy;
    float4 N = tex2D( sampler_pw_noise_lq, uv2 * aspect.xy );
    uv += N.xy;

    ret = lerp(0,rand_preset.xxx*(1.5,-.5,0),GetPixel(frac(uv)).x);
    ret -= lerp(ret,rand_preset*float3(0,1.5,.5),GetBlur1(frac(uv)).y);
