    ret = lerp(ret,rand_preset.yyy*float3(-.45,.25,.5),GetPixel(frac(uv)).y);
    ret = lerp(ret,rand_preset.zzz*float3(1.15,.75,-.2),GetPixel(frac(uv)).z);
    ret -= lerp(-ret,.75,GetPixel(uv_zero).xzy-.125);
    ret = pow(ret,rand_preset-ret);
    ret *= ret;
}

