                  factorA.x*factorB.y + factorA.y*factorB.x);  // the products imaginary part

float3 monkey_saddle = product.x; // (uv^3).x

float2 uv2 =  uv + noise*texsize.zw*8;

ret = tex2d(sampler_fc_main, uv2) + monkey_saddle*0.1 + noise*0.04;

}

